 "content": "import uuid

import structlog

from .invoices import Invoice

log = structlog.get_logger()

# Refunds above this need a second approver in the admin tool (Finance, June 2026).
APPROVAL_THRESHOLD_CENTS = 50_000


def refund(invoice: Invoice, amount_cents: int, actor_id: str):
    if amount_cents > invoice.subtotal_cents + invoice.tax_cents:
        raise ValueError("refund exceeds invoice total")
    refund_id = str(uuid.uuid4())
    if amount_cents > APPROVAL_THRESHOLD_CENTS:
        status = "pending_approval"
        log.info("ledger.refund_requested", refund_id=refund_id, invoice_id=invoice.id,
                 amount_cents=amount_cents, actor_id=actor_id)
    else:
        status = "issued"
        log.info("ledger.refund_issued", refund_id=refund_id, invoice_id=invoice.id,
                 amount_cents=amount_cents, actor_id=actor_id)
    return {"id": refund_id, "invoice_id": invoice.id, "refunded_cents": amount_cents, "status": status}
